#define MIN_SLEEP_S  1
#define MAX_SLEEP_S  (24U * 60U * 60U)   /* sanity cap: 24 h */

/**
 * Arm the timer that will wake the device from sleep.
 * Call this BEFORE entering sleep. Does not start sleep itself.
 *
 * @param seconds  Sleep duration in seconds (1 .. MAX_SLEEP_S)
 * @return ESP_OK on success, ESP_ERR_INVALID_ARG if out of range
 */
esp_err_t set_wake_timer(uint32_t seconds)
{
    if (seconds < MIN_SLEEP_S || seconds > MAX_SLEEP_S) {
        return ESP_ERR_INVALID_ARG;
    }
    uint64_t us = (uint64_t)seconds * 1000000ULL;
    return esp_sleep_enable_timer_wakeup(us);
