```c
#include <time.h>
#include "esp_sleep.h"
#include "esp_timer.h"
#include "esp_log.h"

/* ---- Config: change these to match your needs ---- */
#define SAMPLE_PERIOD_S    60
#define SAMPLES_PER_TX     10     /* transmit trigger: every N samples */
#define CONNECT_TIMEOUT_MS 8000   /* cap the cost of a failed attempt */
#define MAX_BACKOFF_WAKES  64     /* max wakes to skip after repeated failures */

/* ---- Assumed to exist; replace with your real radio code ---- */
esp_err_t radio_connect(uint32_t timeout_ms);
esp_err_t radio_send(const reading_t *r);
void      radio_disconnect(void);
int32_t   read_sensor_scaled(void);

/* State that must survive deep sleep */
static RTC_DATA_ATTR uint8_t  s_fail_count;   /* consecutive failed attempts */
static RTC_DATA_ATTR uint16_t s_skip_wakes;   /* wakes to wait before retrying */

static bool try_transmit(void)
{
    uint16_t sent = 0;
    reading_t r;

    if (radio_connect(CONNECT_TIMEOUT_MS) != ESP_OK) {
        return false;
    }
    while (readings_get(sent, &r) && radio_send(&r) == ESP_OK) {
        sent++;
    }
    radio_disconnect();
    readings_discard(sent);           /* keep unsent readings */
    return readings_count() == 0;     /* true only if everything went out */
}

static void sleep_for_remaining(void)
{
    /* Subtract time spent awake so the sample period doesn't drift */
    uint32_t awake_s = (uint32_t)(esp_timer_get_time() / 1000000ULL);
    uint32_t sleep_s = (awake_s >= SAMPLE_PERIOD_S) ? 1 : SAMPLE_PERIOD_S - awake_s;

    ESP_ERROR_CHECK(set_wake_timer(sleep_s));
    esp_deep_sleep_start();           /* does not return */
}

void app_main(void)
{
    readings_init();                  /* no-op after a normal deep-sleep wake */

    /* 1. Sample (radio stays off) */
    readings_add((uint32_t)time(NULL), read_sensor_scaled());

    /* 2. Decide whether to transmit */
    if (readings_count() >= SAMPLES_PER_TX) {
        if (s_skip_wakes > 0) {
            s_skip_wakes--;           /* backing off after earlier failures */
        } else if (try_transmit()) {
            s_fail_count = 0;
        } else {
            if (s_fail_count < 255) s_fail_count++;
            uint32_t wait = 1U << (s_fail_count < 6 ? s_fail_count : 6);
            if (wait > MAX_BACKOFF_WAKES) wait = MAX_BACKOFF_WAKES;
            s_skip_wakes = (uint16_t)wait;
        }
    }

    /* 3. Sleep */
    sleep_for_remaining();
