Here's a framework-agnostic TypeScript version with sticky percentage bucketing, an override for QA, and a safe fallback to React:

```ts
// checkoutFlag.ts
export type CheckoutImpl = "react" | "svelte";

interface FlagConfig {
  svelteRolloutPercent: number; // 0-100, from your flag service/config
  forceImpl?: CheckoutImpl;     // kill switch or QA override
}

// Deterministic hash so a user always lands in the same bucket
function hashToBucket(id: string): number {
  let h = 2166136261; // FNV-1a
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) % 100;
}

export function pickCheckout(
  userOrSessionId: string,
  config: FlagConfig,
  urlSearch: string = window.location.search
): CheckoutImpl {
  // 1. Kill switch / server-side forced value wins
  if (config.forceImpl) return config.forceImpl;

  // 2. Manual override for QA: ?checkout=svelte
  const override = new URLSearchParams(urlSearch).get("checkout");
  if (override === "react" || override === "svelte") return override;

  // 3. Sticky percentage rollout
  return hashToBucket(userOrSessionId) < config.svelteRolloutPercent
    ? "svelte"
    : "react";
}

export async function loadCheckout(
  userOrSessionId: string,
  config: FlagConfig
) {
  const impl = pickCheckout(userOrSessionId, config);

  if (impl === "svelte") {
    try {
      const { mountCheckout } = await import("./svelte/mountCheckout");
      return { impl, mount: mountCheckout };
    } catch (err) {
      console.error("Svelte checkout failed to load, falling back", err);
    }
  }

  const { mountCheckout } = await import("./react/mountCheckout");
  return { impl: "react" as const, mount: mountCheckout };
}
```

Notes:

- **Both implementations expose the same `mountCheckout(el)` interface**, so the flag is the only place that knows which is which. Dynamic imports keep the unused framework out of the user's bundle.
- **Use a stable ID** (user ID, or a first-party cookie for guests) so people don't flip between implementations mid-funnel.
- **Tag analytics events and error reports with `impl`**, so you can compare conversion and error rates between the two, not just Lighthouse scores.
- For your three phases, you can either ramp `svelteRolloutPercent` or migrate by step and use the flag per step.

