Two design choices shape this. During the migration the build contains both implementations, so a single "total bundle size" budget would fail the moment you add the Svelte chunk. Instead, the script tracks **per-group sizes** and **per-variant totals** (what a user actually downloads: shared + React, or shared + Svelte). Growth is checked against a committed baseline, so any increase has to be an explicit change that shows up in review.

### Chunk naming

The script groups files by filename, so name the checkout chunks. With Vite/Rollup:

```ts
// vite.config.ts
export default defineConfig({
  build: {
    rollupOptions: {
      output: {
        manualChunks(id) {
          if (id.includes('/checkout/react/') || id.includes('node_modules/react')) return 'checkout-react';
          if (id.includes('/checkout/svelte/') || id.includes('node_modules/svelte')) return 'checkout-svelte';
        },
      },
    },
  },
});
```

(On webpack, use `/* webpackChunkName: "checkout-react" */` in the dynamic imports instead. Note that if the rest of your app also uses React, the `node_modules/react` rule will pull it into the checkout chunk, so adjust it to match how your app is structured.)

### The check script

```js
// scripts/bundle-size.mjs
import { readFileSync, writeFileSync, existsSync, readdirSync, appendFileSync } from 'node:fs';
import { brotliCompressSync } from 'node:zlib';
import path from 'node:path';

const DIST = 'dist';
const BASELINE_FILE = 'bundle-baseline.json';
const TOLERANCE_BYTES = 256; // absorbs tiny dependency/compression noise

// First match wins. Order matters.
const GROUPS = [
  ['react-checkout', /checkout-react/],
  ['svelte-checkout', /checkout-svelte/],
  ['shared', /.*/],
];

// What a user downloads under each flag value
const VARIANTS = {
  react: ['shared', 'react-checkout'],
  svelte: ['shared', 'svelte-checkout'],
};

const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    return e.isDirectory() ? walk(p) : [p];
  });

function measure() {
  const groups = Object.fromEntries(GROUPS.map(([name]) => [name, 0]));
  for (const file of walk(DIST).filter((f) => /\.(js|css)$/.test(f))) {
    const rel = path.relative(DIST, file);
    const [group] = GROUPS.find(([, re]) => re.test(rel));
    groups[group] += brotliCompressSync(readFileSync(file)).length;
  }
  const variants = Object.fromEntries(
    Object.entries(VARIANTS).map(([v, gs]) => [v, gs.reduce((sum, g) => sum + groups[g], 0)])
  );
  return { groups, variants };
}

const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
const current = measure();
writeFileSync('bundle-size-current.json', JSON.stringify(current, null, 2));

if (process.argv.includes('--update')) {
  writeFileSync(BASELINE_FILE, JSON.stringify(current, null, 2) + '\n');
  console.log(`Baseline updated:\n${JSON.stringify(current, null, 2)}`);
  process.exit(0);
}

if (!existsSync(BASELINE_FILE)) {
  console.error(`No ${BASELINE_FILE}. Run "npm run size:update" and commit it.`);
  process.exit(1);
}

const baseline = JSON.parse(readFileSync(BASELINE_FILE, 'utf8'));
const rows = [];
let failed = false;

for (const section of ['variants', 'groups']) {
  for (const [name, size] of Object.entries(current[section])) {
    const base = baseline[section]?.[name];
    let status = 'new (not in baseline)';
    if (base !== undefined) {
      const delta = size - base;
      if (delta > TOLERANCE_BYTES) {
        status = `FAIL (+${kb(delta)})`;
        failed = true;
      } else {
        status = delta <= 0 ? `ok (${kb(delta)})` : 'ok';
      }
    }
    rows.push(`| ${section}/${name} | ${base === undefined ? '-' : kb(base)} | ${kb(size)} | ${status} |`);
  }
}

const table = ['| Bundle | Baseline | Current | Status |', '|---|---|---|---|', ...rows].join('\n');
console.log(table);
if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, table + '\n');

if (failed) {
  console.error('\nBundle grew past baseline. If intentional, run "npm run size:update" and commit the new baseline.');
  process.exit(1);
}
```

