```ts
import express from "express";

const router = express.Router();

// ---- Placeholders: wire these to your own implementations ----
declare const db: any;                                   // your DB client
declare function requireAuth(req, res, next): void;      // sets req.user and req.session
declare function rateLimit(opts: { key: (req) => string; max: number; windowSec: number }): express.RequestHandler;
declare function verifyPassword(userId: string, password: string): Promise<boolean>;
declare function generateTotpSecret(): string;           // 20 random bytes, base32
declare function encryptSecret(plain: string): string;   // AES-256-GCM, key from KMS
declare function decryptSecret(blob: string): string;
declare function buildOtpAuthUri(opts: { secret: string; account: string; issuer: string }): string;
declare function verifyTotp(secret: string, code: string): number | null; // matched time step, or null
declare function createBackupCodes(userId: string): Promise<string[]>;   // stores hashes, returns plaintext once
declare function revokeOtherSessions(userId: string, keepSessionId: string): Promise<void>;
declare function notifyUser(userId: string, event: "mfa_enabled"): Promise<void>;
// ---------------------------------------------------------------

// Step 1: start enrollment. Generates a secret but does NOT enable MFA.
router.post(
  "/mfa/totp/enroll",
  requireAuth,
  rateLimit({ key: (req) => `mfa-enroll:${req.user.id}`, max: 5, windowSec: 900 }),
  async (req, res) => {
    const { currentPassword } = req.body ?? {};

    // 1. Re-authenticate so a hijacked session can't register the attacker's device
    if (typeof currentPassword !== "string" || !(await verifyPassword(req.user.id, currentPassword))) {
      return res.status(403).json({ error: "reauth_failed" });
    }

    // 2. Refuse if already enabled; replacing an active factor should go through
    //    a separate disable flow with its own re-auth, never a silent overwrite
    if (req.user.totpEnabledAt) {
      return res.status(409).json({ error: "mfa_already_enabled" });
    }

    // 3. Create (or replace) a pending secret
    const secret = generateTotpSecret();
    await db.query(
      `UPDATE users
          SET totp_secret_encrypted = $1, totp_last_used_step = NULL
        WHERE id = $2 AND totp_enabled_at IS NULL`,
      [encryptSecret(secret), req.user.id]
    );

    // 4. Return the secret once, for QR/manual entry. Never log this response body.
    res.set("Cache-Control", "no-store");
    return res.status(200).json({
      otpauthUri: buildOtpAuthUri({ secret, account: req.user.email, issuer: "YourApp" }),
      secret, // for manual entry
    });
  }
);

// Step 2: confirm enrollment by proving the device generates valid codes.
router.post(
  "/mfa/totp/enroll/verify",
  requireAuth,
  rateLimit({ key: (req) => `mfa-verify:${req.user.id}`, max: 5, windowSec: 900 }),
  async (req, res) => {
    const { code } = req.body ?? {};
    if (typeof code !== "string" || !/^\d{6}$/.test(code)) {
      return res.status(400).json({ error: "invalid_code_format" });
    }

    const { rows } = await db.query(
      `SELECT totp_secret_encrypted, totp_enabled_at FROM users WHERE id = $1`,
      [req.user.id]
    );
    const row = rows[0];

    if (row.totp_enabled_at) return res.status(409).json({ error: "mfa_already_enabled" });
    if (!row.totp_secret_encrypted) return res.status(409).json({ error: "no_pending_enrollment" });

    const step = verifyTotp(decryptSecret(row.totp_secret_encrypted), code);
    if (step === null) return res.status(400).json({ error: "invalid_code" });

    // Atomic enable; the WHERE clause guards against double-submit races
    const result = await db.query(
      `UPDATE users
          SET totp_enabled_at = now(), totp_last_used_step = $1
        WHERE id = $2 AND totp_enabled_at IS NULL`,
      [step, req.user.id]
    );
    if (result.rowCount === 0) return res.status(409).json({ error: "mfa_already_enabled" });

    const backupCodes = await createBackupCodes(req.user.id);   // shown once
    await revokeOtherSessions(req.user.id, req.session.id);
    await notifyUser(req.user.id, "mfa_enabled");               // alerts the real owner if an attacker did this

    res.set("Cache-Control", "no-store");
    return res.status(200).json({ enabled: true, backupCodes });
  }
);

export default router;
```

**Design notes**

- **Two steps:** a mistyped QR scan or abandoned setup can't lock anyone out, because `totp_enabled_at` stays null until a valid code is submitted.
- **Re-auth is only on step 1:** that's where the secret is issued. If you want it tighter, require a fresh session age on step 2 as well.
- **Same-step replay:** `totp_last_used_step` is seeded with the enrollment step, so that exact code can't be reused at login. Your login-time verifier must also check `step > totp_last_used_step` and update it atomically, e.g. `UPDATE ... WHERE totp_last_used_step IS NULL OR totp_last_used_step < $step`.
- **Rate limit:** the limit on verify matters most, since a 6-digit code is guessable without one.
- **Pending secrets never expire:** the schema has no `totp_enrollment_started_at`. That's harmless as long as pending secrets never count as protection, but if you want expiry, add a column and check it in step 2.
- **Verification window:** have `verifyTotp` accept ±1 step at most, and compare codes in constant time (most libraries do).

